#!/bin/sh
# Copy the INTERNAL build into public/ (pages, assets, data). Excludes screenshots and scripts.
set -e; cd "$(dirname "$0")"; A=../app
rm -rf public && mkdir -p public/data
cp $A/*.html public/ && cp -r $A/assets public/ && cp $A/data/portal.js $A/data/portal.json $A/data/properties.js $A/data/contacts.js public/data/
# People who can sign in with the shared PM PIN: the same list as View as (every PM on a job in the build).
node -e "global.window=global;eval(require('fs').readFileSync('$A/data/portal.js','utf8'));const m={};window.PORTAL.jobs.forEach(j=>{if(!j.pm)return;const x=m[j.pm]||(m[j.pm]={name:j.pm,open:0,offs:{}});x.open++;x.offs[j.office||'Office unknown']=(x.offs[j.office||'Office unknown']||0)+1});const L=Object.values(m).map(x=>({name:x.name,office:Object.entries(x.offs).sort((a,b)=>b[1]-a[1])[0][0]})).sort((a,b)=>a.name.localeCompare(b.name));require('fs').writeFileSync('netlify/lib/people.js','// Generated by sync.sh from the portal build. Names only (no secrets).\nexport const PEOPLE = '+JSON.stringify(L)+';\n')"
node gen_index.cjs "$A"
